<?php $active_menu='employee_leave';include 'header.php';require_once __DIR__.'/../foundation.php';oecrm_require_permission($conn,'leave_policies','view');$companyId=oecrm_current_company_id($conn);$flash='';if($_SERVER['REQUEST_METHOD']==='POST'){oecrm_require_csrf();oecrm_require_permission($conn,'leave_policies','edit');if(isset($_POST['policy_id'])){$id=(int)$_POST['policy_id'];$ent=(float)$_POST['annual_entitlement'];$paid=isset($_POST['is_paid'])?1:0;$sandwich=isset($_POST['sandwich_enabled'])?1:0;$half=isset($_POST['allow_half_day'])?1:0;$stmt=mysqli_prepare($conn,'UPDATE leave_policies SET annual_entitlement=?,is_paid=?,sandwich_enabled=?,allow_half_day=? WHERE id=? AND company_id=?');mysqli_stmt_bind_param($stmt,'diiiii',$ent,$paid,$sandwich,$half,$id,$companyId);mysqli_stmt_execute($stmt);mysqli_stmt_close($stmt);mysqli_query($conn,'UPDATE employee_leave_balances b JOIN employeestbl e ON e.id=b.employee_id JOIN leave_policies p ON p.leave_type_id=b.leave_type_id AND p.company_id=e.company_id SET b.credited=p.annual_entitlement WHERE e.company_id='.(int)$companyId.' AND b.balance_year=YEAR(CURDATE())');$flash='Policy updated.';}else{$expiry=max(1,(int)$_POST['comp_off_expiry_days']);$minutes=max(1,(int)$_POST['minimum_comp_off_minutes']);$sandwich=isset($_POST['company_sandwich'])?1:0;$stmt=mysqli_prepare($conn,'UPDATE leave_settings SET comp_off_expiry_days=?,minimum_comp_off_minutes=?,sandwich_enabled=? WHERE company_id=?');mysqli_stmt_bind_param($stmt,'iiii',$expiry,$minutes,$sandwich,$companyId);mysqli_stmt_execute($stmt);mysqli_stmt_close($stmt);$flash='Leave settings updated.';}}$settings=mysqli_fetch_assoc(mysqli_query($conn,'SELECT * FROM leave_settings WHERE company_id='.(int)$companyId));$policies=mysqli_query($conn,'SELECT p.*,t.name FROM leave_policies p JOIN leavetypetbl t ON t.id=p.leave_type_id WHERE p.company_id='.(int)$companyId.' ORDER BY t.name');?>
<div id="page-wrapper" class="compact-admin-page leave-admin-page"><?php if($flash):?><div class="alert alert-success"><?php echo oecrm_h($flash);?></div><?php endif;?><div class="foundation-grid"><div class="panel panel-default"><div class="panel-heading">Global Leave Settings</div><div class="panel-body"><form method="post"><?php echo oecrm_csrf_field();?><div class="form-group"><label>Comp-Off Expiry Days</label><input type="number" class="form-control" name="comp_off_expiry_days" value="<?php echo (int)$settings['comp_off_expiry_days'];?>"></div><div class="form-group"><label>Minimum Minutes for Comp-Off</label><input type="number" class="form-control" name="minimum_comp_off_minutes" value="<?php echo (int)$settings['minimum_comp_off_minutes'];?>"></div><label class="foundation-toggle"><input type="checkbox" name="company_sandwich" <?php echo $settings['sandwich_enabled']?'checked':'';?>> Enable sandwich policy</label><button class="btn btn-primary"><i class="fa fa-save"></i> Save Settings</button></form></div></div><div class="panel panel-default"><div class="panel-heading">Leave Policies</div><div class="panel-body"><div class="policy-grid"><?php while($p=mysqli_fetch_assoc($policies)):?><form method="post" class="policy-card"><?php echo oecrm_csrf_field();?><input type="hidden" name="policy_id" value="<?php echo (int)$p['id'];?>"><h4><?php echo oecrm_h($p['name']);?></h4><div class="form-group"><label>Annual Entitlement</label><input type="number" step="0.5" class="form-control" name="annual_entitlement" value="<?php echo $p['annual_entitlement'];?>"></div><label><input type="checkbox" name="is_paid" <?php echo $p['is_paid']?'checked':'';?>> Paid leave</label><label><input type="checkbox" name="sandwich_enabled" <?php echo $p['sandwich_enabled']?'checked':'';?>> Sandwich applies</label><label><input type="checkbox" name="allow_half_day" <?php echo $p['allow_half_day']?'checked':'';?>> Half-day allowed</label><button class="btn btn-default btn-sm"><i class="fa fa-save"></i> Update</button></form><?php endwhile;?></div></div></div></div></div><?php include 'footer.php';?>